/*! Minimal fallback for Shepherd.js when CDN is unavailable.
   This is NOT the full Shepherd library. It only provides a tiny API-compatible
   facade so the onboarding flow can still run in a degraded way (alert-based).
   For full UI with overlays and tethers, replace this file with the official
   shepherd.min.js from https://github.com/shipshapecode/shepherd */
(function(){
  if (typeof window === 'undefined' || window.Shepherd) return;
  function Tour(opts){ this.options=opts||{}; this.steps=[]; this._handlers={}; this._i=0; }
  Tour.prototype.addStep=function(cfg){ this.steps.push(cfg||{}); };
  Tour.prototype.on=function(evt,fn){ this._handlers[evt]=fn; };
  Tour.prototype.complete=function(){ if(this._handlers.complete) try{ this._handlers.complete(); }catch(e){} };
  Tour.prototype.cancel=function(){ if(this._handlers.cancel) try{ this._handlers.cancel(); }catch(e){} };
  Tour.prototype.start=function(){ this._i=0; this._next(); };
  Tour.prototype._next=function(){
    if(this._i>=this.steps.length){ this.complete(); return; }
    var s=this.steps[this._i++]||{}; var msg=(s.text||'');
    // Degraded UX: show a simple alert with the text; allow the user to proceed.
    setTimeout(function(self){
      try{ alert(String(msg)); }catch(e){}
      self._next();
    }, 10, this);
  };
  window.Shepherd={ Tour: Tour };
})();


